// Regression test for: Price sorting is lexicographic (string) instead of numeric
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #2.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("price sort orders products numerically, not as strings", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Products" })).toBeVisible();

  const productPrices = async () => {
    const prices = await page.locator("main p").filter({ hasText: /^\$\d+/ }).allTextContents();
    return prices.map((t) => t.trim());
  };

  await page.getByRole("button", { name: "Price: low to high" }).click();
  await expect.poll(productPrices).toEqual(["$9", "$14", "$39"]);

  await page.getByRole("button", { name: "Price: high to low" }).click();
  await expect.poll(productPrices).toEqual(["$39", "$14", "$9"]);

  expect(pageErrors).toEqual([]);
});
